insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1d3d5d9f-e05b-42a1-aa15-71ab2d803708', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Functions, Models, and Multiple Representations', 'Calculus begins with functions: rules that connect changing quantities. This unit aligns algebraic, graphical, numerical, and verbal representations so later derivatives and integrals have meaning rather than becoming isolated procedures.', 0),
  ('5c107caf-a015-44e4-8ada-c0b98f11e1e9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '1d3d5d9f-e05b-42a1-aa15-71ab2d803708', 'subtopic'::public.curated_course_node_type, 'Function language and families', 'A strong function toolkit lets students recognize structure before calculating. The goal is to see how a formula''s form controls its graph, domain, range, and behavior.', 0),
  ('0d672b8c-0088-4464-be3d-6a9fdec73ac4', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '5c107caf-a015-44e4-8ada-c0b98f11e1e9', 'concept'::public.curated_course_node_type, 'Domain, range, notation, evaluation, and units', null, 0),
  ('25411ec6-7eb3-42d7-8cf4-35a6cbd19696', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '5c107caf-a015-44e4-8ada-c0b98f11e1e9', 'concept'::public.curated_course_node_type, 'Linear, polynomial, rational, power, radical, exponential, logarithmic, and trigonometric families', null, 1),
  ('b2b39977-850d-4eb4-a6b1-e20154f377ad', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '5c107caf-a015-44e4-8ada-c0b98f11e1e9', 'concept'::public.curated_course_node_type, 'Transformations, composition, inverse functions, and piecewise definitions', null, 2),
  ('935ce93f-4b76-4157-bd0d-9b09f4dd61b5', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '5c107caf-a015-44e4-8ada-c0b98f11e1e9', 'concept'::public.curated_course_node_type, 'Zeros, intercepts, symmetry, periodicity, and asymptotic behavior', null, 3),
  ('e713c337-4966-4e18-bdca-e3c93e3b910d', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '1d3d5d9f-e05b-42a1-aa15-71ab2d803708', 'subtopic'::public.curated_course_node_type, 'Representations and modeling', 'Real problems rarely arrive as clean formulas. Students learn to translate among data, graphs, equations, and descriptions while stating assumptions and checking units.', 1),
  ('29edde4e-e2f3-42ff-91f1-4b2b620988a7', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e713c337-4966-4e18-bdca-e3c93e3b910d', 'concept'::public.curated_course_node_type, 'Building a function from a table, graph, verbal rule, or scientific law', null, 0),
  ('80449ea8-de72-40ea-b049-f8687bc6126b', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e713c337-4966-4e18-bdca-e3c93e3b910d', 'concept'::public.curated_course_node_type, 'Independent and dependent variables; parameters versus variables', null, 1),
  ('137cdf1d-5ad5-4743-b6f8-2223426e2667', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e713c337-4966-4e18-bdca-e3c93e3b910d', 'concept'::public.curated_course_node_type, 'Dimensional analysis and unit consistency', null, 2),
  ('136b05ae-5384-4eeb-ac66-1593999bda83', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e713c337-4966-4e18-bdca-e3c93e3b910d', 'concept'::public.curated_course_node_type, 'Model validity, residual thinking, and limits of extrapolation', null, 3),
  ('04e7dc32-89b6-42dd-a7fe-e96ba401c8ff', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '1d3d5d9f-e05b-42a1-aa15-71ab2d803708', 'subtopic'::public.curated_course_node_type, 'Readiness and mathematical communication', 'Calculus is easier when algebra and trigonometry are automatic and reasoning is written clearly. This strand diagnoses gaps early and establishes habits used throughout the course.', 2),
  ('ca978256-c252-467e-a71a-0a555205b431', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '04e7dc32-89b6-42dd-a7fe-e96ba401c8ff', 'concept'::public.curated_course_node_type, 'Algebraic simplification, factoring, rationalization, and solving equations', null, 0),
  ('6f0660ec-e45a-4209-9999-7ce70f458bc7', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '04e7dc32-89b6-42dd-a7fe-e96ba401c8ff', 'concept'::public.curated_course_node_type, 'Radians, the unit circle, identities, and inverse trigonometric functions', null, 1),
  ('40b7906a-4d43-4b2f-b0ea-3fc82d02f5c1', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '04e7dc32-89b6-42dd-a7fe-e96ba401c8ff', 'concept'::public.curated_course_node_type, 'Exact values versus approximations and sensible rounding', null, 2),
  ('65f76fe0-8f35-4a88-aceb-4017ce753ede', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '04e7dc32-89b6-42dd-a7fe-e96ba401c8ff', 'concept'::public.curated_course_node_type, 'Explaining a conclusion with equations, words, graphs, and units', null, 3),
  ('2647509c-e8db-46df-b53e-f2b2103687f3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Limits and Continuity', 'Limits formalize what a function approaches near a point or far away. They provide the logical foundation for instantaneous rate of change, continuity, asymptotes, and the definite integral.', 1),
  ('464650af-7d7e-43d9-95b5-7cb147ef4667', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2647509c-e8db-46df-b53e-f2b2103687f3', 'subtopic'::public.curated_course_node_type, 'Estimating and computing limits', 'Students first build intuition from graphs and tables, then develop reliable algebraic techniques. The emphasis is on the behavior near a point, not merely the value at the point.', 0),
  ('11bd23cd-7dc9-48c4-969f-fa2f6ec7f139', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '464650af-7d7e-43d9-95b5-7cb147ef4667', 'concept'::public.curated_course_node_type, 'Two-sided and one-sided limits from graphs, tables, and formulas', null, 0),
  ('c8c26510-a6cf-4133-b3aa-43009f04c7d0', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '464650af-7d7e-43d9-95b5-7cb147ef4667', 'concept'::public.curated_course_node_type, 'Limit laws and direct substitution', null, 1),
  ('d31c1e4c-4310-4740-b563-f83e7a33fbd9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '464650af-7d7e-43d9-95b5-7cb147ef4667', 'concept'::public.curated_course_node_type, 'Factoring, rationalizing, common denominators, and trigonometric limits', null, 2),
  ('bbf3804f-2b70-4c34-8376-0a2f18d3d66c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '464650af-7d7e-43d9-95b5-7cb147ef4667', 'concept'::public.curated_course_node_type, 'The Squeeze Theorem and bounding arguments', null, 3),
  ('32bc3d34-660b-4632-b978-ffb858125c90', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2647509c-e8db-46df-b53e-f2b2103687f3', 'subtopic'::public.curated_course_node_type, 'Infinite behavior and asymptotes', 'Limits also describe unbounded growth and long-run behavior. This supports graph analysis and prepares students to reason about scale in scientific and economic models.', 1),
  ('6ff0f27a-9aff-4fd9-b60f-8fb330e4c069', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '32bc3d34-660b-4632-b978-ffb858125c90', 'concept'::public.curated_course_node_type, 'Infinite limits and vertical asymptotes', null, 0),
  ('ed60d3f0-3db8-41e5-96f0-9ef625820048', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '32bc3d34-660b-4632-b978-ffb858125c90', 'concept'::public.curated_course_node_type, 'Limits at infinity and horizontal or slant asymptotes', null, 1),
  ('d65661c8-24b3-483e-9d6e-0862576354e4', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '32bc3d34-660b-4632-b978-ffb858125c90', 'concept'::public.curated_course_node_type, 'Dominant-term reasoning for rational and other functions', null, 2),
  ('0a4583a8-5b8b-453c-b6e4-83b550c5bfb9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '32bc3d34-660b-4632-b978-ffb858125c90', 'concept'::public.curated_course_node_type, 'Distinguishing an infinite limit from a finite limit that fails to exist', null, 3),
  ('8b730be0-ad8d-4d5f-a719-c8e99ecbdb5e', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2647509c-e8db-46df-b53e-f2b2103687f3', 'subtopic'::public.curated_course_node_type, 'Continuity, theorems, and proof awareness', 'Continuity captures when small input changes produce small output changes. Students learn the hypotheses and conclusions of key theorems and gain a first, accessible view of epsilon-delta reasoning.', 2),
  ('199e2f8e-aeaf-48cd-9c79-5b8f7543b566', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '8b730be0-ad8d-4d5f-a719-c8e99ecbdb5e', 'concept'::public.curated_course_node_type, 'Continuity at a point and on an interval', null, 0),
  ('b98938c7-8fb3-4e9f-8e5f-7d285d2fd65a', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '8b730be0-ad8d-4d5f-a719-c8e99ecbdb5e', 'concept'::public.curated_course_node_type, 'Removable, jump, and infinite discontinuities', null, 1),
  ('6f7ee79e-4a78-4222-921c-192bda2f01fd', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '8b730be0-ad8d-4d5f-a719-c8e99ecbdb5e', 'concept'::public.curated_course_node_type, 'Intermediate Value Theorem and existence of roots', null, 2),
  ('7d11dbf4-9b62-4de9-a9f2-d5af1b6b06ca', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '8b730be0-ad8d-4d5f-a719-c8e99ecbdb5e', 'concept'::public.curated_course_node_type, 'Epsilon-delta definition: interpreting and constructing simple estimates', null, 3),
  ('d3288923-bdf6-4d34-b6e1-2372feb31835', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'The Derivative as a Limit and Local Linear Model', 'The derivative measures instantaneous change and gives the best local linear approximation to a differentiable function. This unit connects the geometric tangent, the physical rate, and the analytic limit into one idea.', 2),
  ('cca16f70-3219-4b9e-906e-4f16d15e4997', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd3288923-bdf6-4d34-b6e1-2372feb31835', 'subtopic'::public.curated_course_node_type, 'From average to instantaneous change', 'Secant slopes summarize average change over an interval; a limiting process turns them into tangent slopes and instantaneous rates.', 0),
  ('ccba9ce0-83b4-4174-8942-fdd5b21bde9e', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'cca16f70-3219-4b9e-906e-4f16d15e4997', 'concept'::public.curated_course_node_type, 'Average rate of change and difference quotients', null, 0),
  ('fce8b3ad-2c83-4e14-bc44-74227c554b1c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'cca16f70-3219-4b9e-906e-4f16d15e4997', 'concept'::public.curated_course_node_type, 'Tangent lines, instantaneous velocity, and local rate', null, 1),
  ('3fa4f463-fbdf-401d-ab18-4dcf43033cb6', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'cca16f70-3219-4b9e-906e-4f16d15e4997', 'concept'::public.curated_course_node_type, 'Derivative at a point from the limit definition', null, 2),
  ('a25274df-331e-4020-b8c2-219bfe7a1b04', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'cca16f70-3219-4b9e-906e-4f16d15e4997', 'concept'::public.curated_course_node_type, 'Units and interpretation of f''(a)', null, 3),
  ('0c6dbacb-d9ef-4468-9e77-dff5cf7ba8df', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd3288923-bdf6-4d34-b6e1-2372feb31835', 'subtopic'::public.curated_course_node_type, 'The derivative as a function', 'Treating f'' as a new function reveals how the original function changes everywhere, not just at a single point.', 1),
  ('598048d0-7c6f-41fd-bfe4-8d14317edce5', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '0c6dbacb-d9ef-4468-9e77-dff5cf7ba8df', 'concept'::public.curated_course_node_type, 'Estimating derivative values from data and graphs', null, 0),
  ('1ad34b36-92fb-463d-9241-d5ce76c455a3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '0c6dbacb-d9ef-4468-9e77-dff5cf7ba8df', 'concept'::public.curated_course_node_type, 'Graphing f'' from the graph of f and reconstructing qualitative behavior', null, 1),
  ('1e151b58-50d8-4c2a-ae68-c6dc75ff682d', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '0c6dbacb-d9ef-4468-9e77-dff5cf7ba8df', 'concept'::public.curated_course_node_type, 'Differentiability versus continuity; corners, cusps, vertical tangents, and discontinuities', null, 2),
  ('1ef9222e-470e-4443-b907-cbc3aa00cfc4', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '0c6dbacb-d9ef-4468-9e77-dff5cf7ba8df', 'concept'::public.curated_course_node_type, 'Higher derivatives and changing rates', null, 3),
  ('e56ae088-ec8e-4731-b0ff-a25007b0ecb1', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd3288923-bdf6-4d34-b6e1-2372feb31835', 'subtopic'::public.curated_course_node_type, 'Linearization and differentials', 'A differentiable function behaves nearly linearly at small scales. Linearization turns that insight into a practical approximation and error-estimation tool.', 2),
  ('f55280f7-c42a-49a6-bf07-22a36cd4983c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e56ae088-ec8e-4731-b0ff-a25007b0ecb1', 'concept'::public.curated_course_node_type, 'Tangent-line approximation L(x) = f(a) + f''(a)(x-a)', null, 0),
  ('8beea7b3-8175-46ed-a225-52e8f2e6c683', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e56ae088-ec8e-4731-b0ff-a25007b0ecb1', 'concept'::public.curated_course_node_type, 'Differentials and propagation of small measurement changes', null, 1),
  ('11768ab1-f8dd-4b5a-9c1b-b12e81872d6f', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e56ae088-ec8e-4731-b0ff-a25007b0ecb1', 'concept'::public.curated_course_node_type, 'Relative and percentage error', null, 2),
  ('3ba2bf02-89dc-4d5e-a873-67117cf112fc', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'e56ae088-ec8e-4731-b0ff-a25007b0ecb1', 'concept'::public.curated_course_node_type, 'When a local approximation is trustworthy', null, 3),
  ('38df6638-3cf4-4e3a-b0cf-a444ac8cc903', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Differentiation Rules and Transcendental Functions', 'Once the derivative is understood as a limit, differentiation rules make it efficient to analyze realistic functions. The aim is fluent computation supported by structural reasoning and quick plausibility checks.', 3),
  ('7a02158f-54ef-4ae6-93b9-35ca9218dcc5', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '38df6638-3cf4-4e3a-b0cf-a444ac8cc903', 'subtopic'::public.curated_course_node_type, 'Core algebraic rules', 'The basic rules convert products, quotients, powers, and sums into manageable derivatives while preserving the structure of the original function.', 0),
  ('67d0772f-32e0-4c22-a0c9-467e81d17dcb', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '7a02158f-54ef-4ae6-93b9-35ca9218dcc5', 'concept'::public.curated_course_node_type, 'Constant, power, constant-multiple, sum, and difference rules', null, 0),
  ('4bbed588-f910-49b5-9a64-0a8d2025eeea', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '7a02158f-54ef-4ae6-93b9-35ca9218dcc5', 'concept'::public.curated_course_node_type, 'Product and quotient rules', null, 1),
  ('53648911-bd02-43d2-b487-d96df57655cf', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '7a02158f-54ef-4ae6-93b9-35ca9218dcc5', 'concept'::public.curated_course_node_type, 'Combining rules in multi-step expressions', null, 2),
  ('9e2e5383-c07d-4d58-8e05-f9cb3d456f27', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '7a02158f-54ef-4ae6-93b9-35ca9218dcc5', 'concept'::public.curated_course_node_type, 'Checking results by units, signs, special values, or numerical slopes', null, 3),
  ('2d730c50-5f6e-4b0f-8afe-f0215659c00a', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '38df6638-3cf4-4e3a-b0cf-a444ac8cc903', 'subtopic'::public.curated_course_node_type, 'The chain rule', 'Composite functions represent nested processes. The chain rule tracks how change propagates through each layer and is central to science, engineering, economics, and computation.', 1),
  ('9018d516-d6e3-4162-a368-b2799968bb1a', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2d730c50-5f6e-4b0f-8afe-f0215659c00a', 'concept'::public.curated_course_node_type, 'Identifying inner and outer functions', null, 0),
  ('149feea9-10ca-42e9-9799-76957192e078', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2d730c50-5f6e-4b0f-8afe-f0215659c00a', 'concept'::public.curated_course_node_type, 'Chain rule for algebraic, trigonometric, exponential, and logarithmic compositions', null, 1),
  ('1e3c5e23-1c81-4b3a-a1f4-ff301081c2ec', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2d730c50-5f6e-4b0f-8afe-f0215659c00a', 'concept'::public.curated_course_node_type, 'Repeated nesting and multiple rule combinations', null, 2),
  ('c0f5bc00-2f5c-4b61-a9dc-6a68b8e0b435', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2d730c50-5f6e-4b0f-8afe-f0215659c00a', 'concept'::public.curated_course_node_type, 'Sensitivity interpretation through rates multiplied along a dependency chain', null, 3),
  ('6dad3617-5039-4878-a088-859ac36cbb6c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '38df6638-3cf4-4e3a-b0cf-a444ac8cc903', 'subtopic'::public.curated_course_node_type, 'Standard transcendental derivatives', 'Exponential, logarithmic, and trigonometric functions describe growth, decay, oscillation, rotation, and scaling. Their derivatives make these models analytically useful.', 2),
  ('bcd82b17-3b13-4320-a6cb-2e8570c78f63', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6dad3617-5039-4878-a088-859ac36cbb6c', 'concept'::public.curated_course_node_type, 'Derivatives of e^x, a^x, ln(x), and log_a(x)', null, 0),
  ('68c82d61-33d3-479c-b775-9a57a22f658e', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6dad3617-5039-4878-a088-859ac36cbb6c', 'concept'::public.curated_course_node_type, 'Derivatives of sine, cosine, tangent, and reciprocal trigonometric functions', null, 1),
  ('2586c684-14e6-4757-9950-880b1d6f66a3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6dad3617-5039-4878-a088-859ac36cbb6c', 'concept'::public.curated_course_node_type, 'Higher-order derivatives and cyclic patterns', null, 2),
  ('d1f40447-df2d-46a7-8eae-756023cda700', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6dad3617-5039-4878-a088-859ac36cbb6c', 'concept'::public.curated_course_node_type, 'Applications to growth, decay, oscillation, and elasticity-like rates', null, 3),
  ('15d196d9-24c2-4805-9419-6b01a9bca929', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Implicit, Inverse, and Logarithmic Differentiation', 'Many important relationships are not solved explicitly for one variable. These techniques extend differentiation to curves, inverse relationships, and complicated products or powers.', 4),
  ('47e1fd94-1328-4c51-8ce1-e3764a587d00', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '15d196d9-24c2-4805-9419-6b01a9bca929', 'subtopic'::public.curated_course_node_type, 'Implicit differentiation', 'Implicit differentiation finds rates on a relation F(x,y)=0 without first isolating y, which is often impossible or undesirable.', 0),
  ('7e2fa40b-8d28-4596-ac98-d30e3f781f4a', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '47e1fd94-1328-4c51-8ce1-e3764a587d00', 'concept'::public.curated_course_node_type, 'Differentiating both sides while treating y as a function of x', null, 0),
  ('088cc832-41cd-44b2-9ce5-4a6202f23e01', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '47e1fd94-1328-4c51-8ce1-e3764a587d00', 'concept'::public.curated_course_node_type, 'Solving for dy/dx and evaluating at a point', null, 1),
  ('94609c63-06c2-4156-9334-b37fdf6ab4d5', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '47e1fd94-1328-4c51-8ce1-e3764a587d00', 'concept'::public.curated_course_node_type, 'Tangent and normal lines to implicit curves', null, 2),
  ('6dfa9ed7-89db-44ef-9d82-bfa49910a243', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '47e1fd94-1328-4c51-8ce1-e3764a587d00', 'concept'::public.curated_course_node_type, 'Second derivatives and geometric interpretation', null, 3),
  ('220e547f-b0da-4b7d-998b-c74d718b5f50', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '15d196d9-24c2-4805-9419-6b01a9bca929', 'subtopic'::public.curated_course_node_type, 'Inverse functions and inverse trigonometric derivatives', 'The derivative of an inverse reverses the input-output relationship. This gives a general principle and the formulas for inverse trigonometric functions.', 1),
  ('ea6f02ed-c48c-42bc-a0b2-bfb117ce6ffe', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '220e547f-b0da-4b7d-998b-c74d718b5f50', 'concept'::public.curated_course_node_type, 'Conditions for local and global invertibility', null, 0),
  ('944cafe8-1608-45e3-93fd-9dba7e45ca97', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '220e547f-b0da-4b7d-998b-c74d718b5f50', 'concept'::public.curated_course_node_type, 'Derivative of an inverse function', null, 1),
  ('604cb4d1-46f8-4380-aacf-bf0f43638523', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '220e547f-b0da-4b7d-998b-c74d718b5f50', 'concept'::public.curated_course_node_type, 'Derivatives of arcsine, arccosine, arctangent, and related functions', null, 2),
  ('f87a8350-718d-43c8-a33f-19fe5e01514b', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '220e547f-b0da-4b7d-998b-c74d718b5f50', 'concept'::public.curated_course_node_type, 'Interpreting reciprocal slopes and domain restrictions', null, 3),
  ('6c5febba-b63c-4179-9be1-6b831afe4c9d', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '15d196d9-24c2-4805-9419-6b01a9bca929', 'subtopic'::public.curated_course_node_type, 'Logarithmic differentiation', 'Taking logarithms can turn products into sums and variable powers into products, making otherwise difficult derivatives systematic.', 2),
  ('a0097d21-e521-4642-a67f-d7274dd2e833', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6c5febba-b63c-4179-9be1-6b831afe4c9d', 'concept'::public.curated_course_node_type, 'Products and quotients with many factors', null, 0),
  ('750a49b5-f9f9-4bbf-9b63-f14e3f08d4f6', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6c5febba-b63c-4179-9be1-6b831afe4c9d', 'concept'::public.curated_course_node_type, 'Functions of the form u(x)^v(x)', null, 1),
  ('2dc603b1-f56e-403e-9f6f-79b95f123efd', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6c5febba-b63c-4179-9be1-6b831afe4c9d', 'concept'::public.curated_course_node_type, 'Absolute values in logarithmic identities where required', null, 2),
  ('741d643f-3ce7-40fd-853b-add471987c16', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '6c5febba-b63c-4179-9be1-6b831afe4c9d', 'concept'::public.curated_course_node_type, 'Comparing logarithmic differentiation with direct rules', null, 3),
  ('43db1e3a-b82c-4f63-b983-746146016d6d', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Theorems, Curve Analysis, and Indeterminate Forms', 'Derivatives reveal global information about a function when combined with theorem hypotheses. This unit turns local slope data into a disciplined account of extrema, shape, approximation, and limiting behavior.', 5),
  ('add9fa98-d38a-418c-a69b-bb35bbdc7f96', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '43db1e3a-b82c-4f63-b983-746146016d6d', 'subtopic'::public.curated_course_node_type, 'Extrema and the Mean Value Theorem', 'Existence theorems say when extrema or intermediate slopes must occur. Students learn to check hypotheses before using conclusions.', 0),
  ('70f560f3-e4cb-4045-a416-dcc3f5203225', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'add9fa98-d38a-418c-a69b-bb35bbdc7f96', 'concept'::public.curated_course_node_type, 'Absolute and local extrema; critical numbers and endpoints', null, 0),
  ('8f086104-eb17-46c6-ae9d-45775f9a801c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'add9fa98-d38a-418c-a69b-bb35bbdc7f96', 'concept'::public.curated_course_node_type, 'Extreme Value Theorem and closed-interval method', null, 1),
  ('f8faebb5-3388-4073-af30-54565c0cc1bc', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'add9fa98-d38a-418c-a69b-bb35bbdc7f96', 'concept'::public.curated_course_node_type, 'Rolle''s Theorem and the Mean Value Theorem', null, 2),
  ('2f349522-ef3a-40da-8f01-d1583d627ab5', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'add9fa98-d38a-418c-a69b-bb35bbdc7f96', 'concept'::public.curated_course_node_type, 'Consequences: monotonicity, constant functions, and derivative comparisons', null, 3),
  ('3e0209c1-9bc3-4275-889b-de4bedc28bb9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '43db1e3a-b82c-4f63-b983-746146016d6d', 'subtopic'::public.curated_course_node_type, 'First- and second-derivative analysis', 'Sign charts for f'' and f'''' translate derivative information into a reliable sketch and a qualitative description of behavior.', 1),
  ('029184c1-49ef-49e9-93b8-7ad79be21164', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3e0209c1-9bc3-4275-889b-de4bedc28bb9', 'concept'::public.curated_course_node_type, 'Increasing and decreasing intervals', null, 0),
  ('1886ccde-6857-4adc-adf4-1ef7ca18a102', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3e0209c1-9bc3-4275-889b-de4bedc28bb9', 'concept'::public.curated_course_node_type, 'First-derivative test for local extrema', null, 1),
  ('37ad2885-67bb-4f05-9c35-bbcf35624a39', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3e0209c1-9bc3-4275-889b-de4bedc28bb9', 'concept'::public.curated_course_node_type, 'Concavity, inflection points, and the second-derivative test', null, 2),
  ('ea55584e-1beb-4dd9-80c8-6b51304ec278', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3e0209c1-9bc3-4275-889b-de4bedc28bb9', 'concept'::public.curated_course_node_type, 'Complete curve analysis including domain, intercepts, symmetry, and asymptotes', null, 3),
  ('10d79370-b533-447c-b1fd-e7c587348a7b', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '43db1e3a-b82c-4f63-b983-746146016d6d', 'subtopic'::public.curated_course_node_type, 'L''Hopital''s Rule and approximation behavior', 'Indeterminate forms signal competition between quantities. L''Hopital''s Rule is useful only after the form and its conditions have been verified.', 2),
  ('b2c64381-6c18-44d4-b8c0-2cad0fc2798c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '10d79370-b533-447c-b1fd-e7c587348a7b', 'concept'::public.curated_course_node_type, 'Recognizing 0/0 and infinity/infinity forms', null, 0),
  ('de6d9e76-29e7-4c44-adcb-635de9763ab2', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '10d79370-b533-447c-b1fd-e7c587348a7b', 'concept'::public.curated_course_node_type, 'Applying L''Hopital''s Rule and deciding when to repeat it', null, 1),
  ('85749178-496b-43a3-ae6a-760ba77e49ea', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '10d79370-b533-447c-b1fd-e7c587348a7b', 'concept'::public.curated_course_node_type, 'Comparing L''Hopital with algebraic, trigonometric, or dominant-term methods', null, 2),
  ('a410bf0c-6252-4a01-b7ca-bab58de47f30', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '10d79370-b533-447c-b1fd-e7c587348a7b', 'concept'::public.curated_course_node_type, 'Avoiding misuse when the hypotheses fail', null, 3),
  ('2f6cab90-79c3-45c1-a2d4-c72cc0f6035c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Applied Rates, Motion, and Related-Rate Models', 'Calculus becomes powerful when derivatives are attached to quantities with units. This unit develops a repeatable modeling workflow for motion and for systems in which several variables change together.', 6),
  ('4cd2c7fd-a8be-43b0-a9df-908a686d3a57', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2f6cab90-79c3-45c1-a2d4-c72cc0f6035c', 'subtopic'::public.curated_course_node_type, 'Motion and rate interpretation', 'Position, velocity, and acceleration provide a concrete setting for first and second derivatives and for interpreting signs and accumulated change.', 0),
  ('d11ddfc7-4921-4c78-8812-8709389fc094', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '4cd2c7fd-a8be-43b0-a9df-908a686d3a57', 'concept'::public.curated_course_node_type, 'Position, displacement, distance, velocity, speed, and acceleration', null, 0),
  ('1f3e0c59-0e98-4a5d-861a-2bd3027c8073', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '4cd2c7fd-a8be-43b0-a9df-908a686d3a57', 'concept'::public.curated_course_node_type, 'Units and sign conventions', null, 1),
  ('4f1e29c6-1bbe-4589-98cc-d17a37c4c33d', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '4cd2c7fd-a8be-43b0-a9df-908a686d3a57', 'concept'::public.curated_course_node_type, 'Reading motion from formulas, graphs, and data', null, 2),
  ('2ed142b3-a066-4180-93df-ba31b11cf4f5', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '4cd2c7fd-a8be-43b0-a9df-908a686d3a57', 'concept'::public.curated_course_node_type, 'Connecting turning points and concavity to physical behavior', null, 3),
  ('a1597e1f-0b7f-4b2d-948a-9f8138996d75', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2f6cab90-79c3-45c1-a2d4-c72cc0f6035c', 'subtopic'::public.curated_course_node_type, 'Related-rates workflow', 'Related-rates problems test modeling more than algebra. Students identify the governing relation, differentiate before substituting, and interpret the signed result.', 1),
  ('0181382e-23f2-4ea0-ab16-1a32b6cb5413', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'a1597e1f-0b7f-4b2d-948a-9f8138996d75', 'concept'::public.curated_course_node_type, 'Define variables as functions of time and draw a labeled diagram', null, 0),
  ('0a14c6b0-5f97-42b5-99b0-5df42680cdae', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'a1597e1f-0b7f-4b2d-948a-9f8138996d75', 'concept'::public.curated_course_node_type, 'Write one relation connecting the changing quantities', null, 1),
  ('eefbece4-9db7-4e11-b714-b11f58de70f3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'a1597e1f-0b7f-4b2d-948a-9f8138996d75', 'concept'::public.curated_course_node_type, 'Differentiate implicitly with respect to time', null, 2),
  ('695be1ed-887f-48e1-94d0-e2b715fc635f', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'a1597e1f-0b7f-4b2d-948a-9f8138996d75', 'concept'::public.curated_course_node_type, 'Substitute the instant-specific data, solve, and report units', null, 3),
  ('800020cc-44e8-4bc0-aafe-631df13045f6', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2f6cab90-79c3-45c1-a2d4-c72cc0f6035c', 'subtopic'::public.curated_course_node_type, 'Cross-disciplinary rate models', 'A shared calculus structure appears across disciplines even when the vocabulary changes. Problems are selected so every degree sees both familiar and unfamiliar contexts.', 2),
  ('95cab18f-d6c1-4541-b11c-194809b77dcc', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '800020cc-44e8-4bc0-aafe-631df13045f6', 'concept'::public.curated_course_node_type, 'Biology and chemistry: population change, reaction rates, and concentration', null, 0),
  ('a305d480-1978-4455-a295-01d54bc78424', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '800020cc-44e8-4bc0-aafe-631df13045f6', 'concept'::public.curated_course_node_type, 'Engineering: expanding geometry, fluid levels, heat, motion, and sensor error', null, 1),
  ('1c4be7bc-2e68-4ee4-8dac-a907eb54feba', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '800020cc-44e8-4bc0-aafe-631df13045f6', 'concept'::public.curated_course_node_type, 'Economics: marginal quantities and rates of cost, revenue, and demand change', null, 2),
  ('f57a0d69-9e90-481a-a7a2-63f37b79f5bd', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '800020cc-44e8-4bc0-aafe-631df13045f6', 'concept'::public.curated_course_node_type, 'Computer science: throughput, scaling trends, and continuous approximations to discrete change', null, 3),
  ('003d9172-6636-4b80-82ba-ea7bd40a4c4e', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Optimization and Newton''s Method', 'Optimization turns a context into an objective function, a feasible domain, and a justified best choice. Newton''s method complements exact analysis with an iterative approach to solving nonlinear equations.', 7),
  ('bf6f0d1d-27c7-46d4-8248-cbadc7418e43', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '003d9172-6636-4b80-82ba-ea7bd40a4c4e', 'subtopic'::public.curated_course_node_type, 'Optimization modeling', 'The central challenge is building the right function and domain. Calculus then identifies candidates, while context decides which candidates are meaningful.', 0),
  ('a9957816-378c-46ca-a439-e03423cb2c45', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'bf6f0d1d-27c7-46d4-8248-cbadc7418e43', 'concept'::public.curated_course_node_type, 'Objective, decision variables, constraints, and feasible intervals', null, 0),
  ('1701b11a-485c-40ce-a83e-09d3427a0778', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'bf6f0d1d-27c7-46d4-8248-cbadc7418e43', 'concept'::public.curated_course_node_type, 'Reducing a multi-quantity problem to one variable', null, 1),
  ('e8543636-f9e2-4d09-82d0-d32bd1a3d7bf', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'bf6f0d1d-27c7-46d4-8248-cbadc7418e43', 'concept'::public.curated_course_node_type, 'Critical points, endpoints, and global comparison', null, 2),
  ('2519d04b-cb47-47de-82ea-d7f6a403e074', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'bf6f0d1d-27c7-46d4-8248-cbadc7418e43', 'concept'::public.curated_course_node_type, 'Interpreting sensitivity, units, and practical constraints', null, 3),
  ('2875b0ac-2f9c-40b7-ab2a-073f40fbd243', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '003d9172-6636-4b80-82ba-ea7bd40a4c4e', 'subtopic'::public.curated_course_node_type, 'Discipline-specific optimization', 'Different fields ask different questions, but the mathematical architecture is the same: define, differentiate, test, and interpret.', 1),
  ('b35fd450-e4d4-430b-ae44-32cb021c4098', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2875b0ac-2f9c-40b7-ab2a-073f40fbd243', 'concept'::public.curated_course_node_type, 'Engineering design: material, energy, geometry, and performance tradeoffs', null, 0),
  ('894740d3-e544-4563-8a88-695fede941f0', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2875b0ac-2f9c-40b7-ab2a-073f40fbd243', 'concept'::public.curated_course_node_type, 'Economics: profit, revenue, cost, and elasticity-aware decisions', null, 1),
  ('ff1bd33b-aac5-48be-8e47-8433910cb168', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2875b0ac-2f9c-40b7-ab2a-073f40fbd243', 'concept'::public.curated_course_node_type, 'Biology and chemistry: yield, dose, growth, and reaction conditions', null, 2),
  ('dded3e38-e035-4f4b-b77a-94e6a0744b4a', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2875b0ac-2f9c-40b7-ab2a-073f40fbd243', 'concept'::public.curated_course_node_type, 'Computing: continuous relaxations of resource and performance choices', null, 3),
  ('3fe1a520-ef3d-4236-a0d9-5b03b5acfe35', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '003d9172-6636-4b80-82ba-ea7bd40a4c4e', 'subtopic'::public.curated_course_node_type, 'Newton''s method and numerical roots', 'Newton''s method uses tangent-line approximations to refine a root estimate. It is a first example of an algorithm whose success depends on both mathematics and initial conditions.', 2),
  ('3afd6c58-baf8-49d7-951a-1e6b9520af90', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3fe1a520-ef3d-4236-a0d9-5b03b5acfe35', 'concept'::public.curated_course_node_type, 'Deriving x_(n+1) = x_n - f(x_n)/f''(x_n) from linearization', null, 0),
  ('892f472d-b33d-4ab8-8668-cb0107964bed', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3fe1a520-ef3d-4236-a0d9-5b03b5acfe35', 'concept'::public.curated_course_node_type, 'Iteration tables and stopping criteria', null, 1),
  ('5074d8b0-8acf-44b4-9bee-ed98d3dafbb9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3fe1a520-ef3d-4236-a0d9-5b03b5acfe35', 'concept'::public.curated_course_node_type, 'Convergence, failure, cycling, and poor initial guesses', null, 2),
  ('768ad435-4ac4-4cd1-a4c0-93e42bfccae9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3fe1a520-ef3d-4236-a0d9-5b03b5acfe35', 'concept'::public.curated_course_node_type, 'Comparing Newton''s method with graphing and bisection ideas', null, 3),
  ('2cb3d932-f58d-4afa-a651-0d5839f5c35c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Antiderivatives and Introductory Differential Equations', 'Antidifferentiation reverses differentiation, while differential equations express laws in terms of rates. This unit links families of functions, initial conditions, and simple dynamic models.', 8),
  ('162751cb-c99f-48df-9ca0-69d9232eb06c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2cb3d932-f58d-4afa-a651-0d5839f5c35c', 'subtopic'::public.curated_course_node_type, 'Antiderivatives and indefinite integrals', 'Because differentiation loses constants, reversing it produces a family of functions. Students build a compact library of antiderivative patterns.', 0),
  ('a92c9d01-d247-4231-8f59-af700c1b6a66', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '162751cb-c99f-48df-9ca0-69d9232eb06c', 'concept'::public.curated_course_node_type, 'Power, exponential, logarithmic, and basic trigonometric antiderivatives', null, 0),
  ('d0f903f5-6824-466b-9f27-79bff198db03', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '162751cb-c99f-48df-9ca0-69d9232eb06c', 'concept'::public.curated_course_node_type, 'Linearity and algebraic simplification before integration', null, 1),
  ('444706d2-2826-4d0e-a6ac-c9aa8c6f8df3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '162751cb-c99f-48df-9ca0-69d9232eb06c', 'concept'::public.curated_course_node_type, 'The constant of integration and families of curves', null, 2),
  ('a2093cee-f597-42d9-8d1f-2e615ac330f8', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '162751cb-c99f-48df-9ca0-69d9232eb06c', 'concept'::public.curated_course_node_type, 'Checking an antiderivative by differentiation', null, 3),
  ('147b9155-508d-4d72-b72c-7d3b81b6263c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2cb3d932-f58d-4afa-a651-0d5839f5c35c', 'subtopic'::public.curated_course_node_type, 'Initial-value problems', 'An initial condition selects one member from an antiderivative family. This provides a direct bridge from rate laws to predictions.', 1),
  ('02e80418-d390-4db4-9c18-19ee97291ee3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '147b9155-508d-4d72-b72c-7d3b81b6263c', 'concept'::public.curated_course_node_type, 'Recovering position from velocity or acceleration', null, 0),
  ('76046b73-bb55-4a05-907e-4879d6e224f1', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '147b9155-508d-4d72-b72c-7d3b81b6263c', 'concept'::public.curated_course_node_type, 'Solving y'' = f(x) with y(a) specified', null, 1),
  ('2cd02751-b320-4a04-ae55-99a622892820', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '147b9155-508d-4d72-b72c-7d3b81b6263c', 'concept'::public.curated_course_node_type, 'Interpreting constants from contextual data', null, 2),
  ('08d805ec-e996-4754-8afb-56b9545757c1', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '147b9155-508d-4d72-b72c-7d3b81b6263c', 'concept'::public.curated_course_node_type, 'Verifying a proposed solution and its units', null, 3),
  ('c70a3264-a1d3-4079-9f68-a9eeb712b372', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '2cb3d932-f58d-4afa-a651-0d5839f5c35c', 'subtopic'::public.curated_course_node_type, 'Simple growth and change models', 'Even before a full differential-equations course, students can analyze basic rate models and connect qualitative behavior to a derivative law.', 2),
  ('78426cb5-deae-4afd-975b-9ea1a40e3b98', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c70a3264-a1d3-4079-9f68-a9eeb712b372', 'concept'::public.curated_course_node_type, 'Constant-rate and proportional-rate models', null, 0),
  ('2f3522b6-3b00-4701-b573-6eaaa6cddb8c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c70a3264-a1d3-4079-9f68-a9eeb712b372', 'concept'::public.curated_course_node_type, 'Exponential growth and decay', null, 1),
  ('b34a35db-e707-4d6a-8647-97d514bc6f67', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c70a3264-a1d3-4079-9f68-a9eeb712b372', 'concept'::public.curated_course_node_type, 'Direction-field interpretation at an introductory level', null, 2),
  ('5b8a51be-148f-402d-aec8-8d0ed9ca4a92', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c70a3264-a1d3-4079-9f68-a9eeb712b372', 'concept'::public.curated_course_node_type, 'Model assumptions, parameter meaning, and long-run behavior', null, 3),
  ('cb69f888-ff45-47c9-9556-8d5c765046e3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Riemann Sums and the Definite Integral', 'The definite integral measures net accumulation as a limit of many small contributions. Riemann sums make that construction explicit and connect data-based estimates to exact calculus.', 9),
  ('c6c6bf34-c51d-432b-a0cc-c61a7cfbd881', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'cb69f888-ff45-47c9-9556-8d5c765046e3', 'subtopic'::public.curated_course_node_type, 'Accumulation from finite sums', 'Before taking a limit, students approximate accumulation with rectangles or data intervals and interpret each term as rate times input change.', 0),
  ('bba8ef10-6b14-4036-98f1-620a95e7611e', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c6c6bf34-c51d-432b-a0cc-c61a7cfbd881', 'concept'::public.curated_course_node_type, 'Partitions, subinterval width, and sample points', null, 0),
  ('8ad3cba3-2455-4fcc-add2-c056eed4e04c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c6c6bf34-c51d-432b-a0cc-c61a7cfbd881', 'concept'::public.curated_course_node_type, 'Left, right, midpoint, and general Riemann sums', null, 1),
  ('11ead34c-8c45-4b30-8d1e-cb72b338dc02', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c6c6bf34-c51d-432b-a0cc-c61a7cfbd881', 'concept'::public.curated_course_node_type, 'Sigma notation and dimensional meaning', null, 2),
  ('4a8bfd20-e2de-460b-8a00-e7af3b87e6eb', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c6c6bf34-c51d-432b-a0cc-c61a7cfbd881', 'concept'::public.curated_course_node_type, 'Overestimates, underestimates, and refinement', null, 3),
  ('c7499fa5-64ed-4154-9d72-458fc47d9113', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'cb69f888-ff45-47c9-9556-8d5c765046e3', 'subtopic'::public.curated_course_node_type, 'The definite integral as a limit', 'Letting the mesh width shrink defines a number independent of a particular rectangle choice for integrable functions.', 1),
  ('3de7b415-f7c7-4018-b048-02a6538a0c0c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c7499fa5-64ed-4154-9d72-458fc47d9113', 'concept'::public.curated_course_node_type, 'Limit definition of the definite integral', null, 0),
  ('d9224d8b-f29a-4c9e-9319-c9ec5ea1f5fc', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c7499fa5-64ed-4154-9d72-458fc47d9113', 'concept'::public.curated_course_node_type, 'Signed area and orientation', null, 1),
  ('deb24b8f-018a-48f4-a779-8e915896b606', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c7499fa5-64ed-4154-9d72-458fc47d9113', 'concept'::public.curated_course_node_type, 'Basic properties: additivity, linearity, comparison, and bounds', null, 2),
  ('cb217b90-8988-42f4-968f-be0e413b2a0f', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'c7499fa5-64ed-4154-9d72-458fc47d9113', 'concept'::public.curated_course_node_type, 'Integrability and the role of continuity', null, 3),
  ('14b159db-8ce2-4ef8-8559-6eef9d1a9ce6', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'cb69f888-ff45-47c9-9556-8d5c765046e3', 'subtopic'::public.curated_course_node_type, 'Integral interpretation from graphs and data', 'A definite integral is not automatically geometric area; its meaning depends on the integrand and units.', 2),
  ('68d78eef-61b3-4e3c-a307-4039295fc962', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '14b159db-8ce2-4ef8-8559-6eef9d1a9ce6', 'concept'::public.curated_course_node_type, 'Net change from a rate graph', null, 0),
  ('d1c5a078-137a-4004-98eb-b2a22418fbfe', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '14b159db-8ce2-4ef8-8559-6eef9d1a9ce6', 'concept'::public.curated_course_node_type, 'Geometric evaluation using familiar shapes and symmetry', null, 1),
  ('69c775e8-ebb0-4151-bf73-9940949ee960', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '14b159db-8ce2-4ef8-8559-6eef9d1a9ce6', 'concept'::public.curated_course_node_type, 'Estimating from tabulated measurements', null, 2),
  ('0798cc38-c78e-4a1d-8d84-b22825a77362', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '14b159db-8ce2-4ef8-8559-6eef9d1a9ce6', 'concept'::public.curated_course_node_type, 'Distinguishing net accumulation from total accumulation', null, 3),
  ('959cdbf9-547d-4c06-b929-0c25d15900be', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'The Fundamental Theorem of Calculus and Net Change', 'The Fundamental Theorem of Calculus unifies the course: differentiation and integration are inverse processes. It turns a limiting sum into a computable quantity and explains accumulation functions.', 10),
  ('283c4b83-4143-48f1-8e85-a81c8d8cba02', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '959cdbf9-547d-4c06-b929-0c25d15900be', 'subtopic'::public.curated_course_node_type, 'Accumulation functions and FTC Part I', 'An integral with a variable endpoint defines a new function. Its derivative recovers the original integrand under appropriate conditions.', 0),
  ('354a72e9-e635-4b78-abca-80070135575e', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '283c4b83-4143-48f1-8e85-a81c8d8cba02', 'concept'::public.curated_course_node_type, 'Functions defined by accumulated area or net change', null, 0),
  ('f8ff4dd6-e0ab-49dc-bf4a-8c07cd156725', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '283c4b83-4143-48f1-8e85-a81c8d8cba02', 'concept'::public.curated_course_node_type, 'Derivative of an integral with a variable upper limit', null, 1),
  ('b219f37c-0598-4666-964e-6353f3bd0bcb', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '283c4b83-4143-48f1-8e85-a81c8d8cba02', 'concept'::public.curated_course_node_type, 'Chain rule with variable limits', null, 2),
  ('cb29932c-cd28-4967-9997-0b2be1094df6', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '283c4b83-4143-48f1-8e85-a81c8d8cba02', 'concept'::public.curated_course_node_type, 'Graphical interpretation of an accumulation function and its derivative', null, 3),
  ('ea129084-8dbd-4dde-9b82-7d82e337f334', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '959cdbf9-547d-4c06-b929-0c25d15900be', 'subtopic'::public.curated_course_node_type, 'Evaluating definite integrals and FTC Part II', 'An antiderivative collapses an infinite limiting process into endpoint subtraction, making exact accumulation practical.', 1),
  ('7ba28edd-e221-48d7-bb2c-04e0d437f345', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'ea129084-8dbd-4dde-9b82-7d82e337f334', 'concept'::public.curated_course_node_type, 'Evaluation formula F(b) - F(a)', null, 0),
  ('89750d3f-3167-46f5-8572-ac38212bd2d9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'ea129084-8dbd-4dde-9b82-7d82e337f334', 'concept'::public.curated_course_node_type, 'Choosing and verifying an antiderivative', null, 1),
  ('594ecc70-7c7b-4a47-becf-6dabab2ab3dc', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'ea129084-8dbd-4dde-9b82-7d82e337f334', 'concept'::public.curated_course_node_type, 'Orientation, interval splitting, and signed results', null, 2),
  ('905f21ad-b7cd-4ee1-b252-bdc9f7e5fd89', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'ea129084-8dbd-4dde-9b82-7d82e337f334', 'concept'::public.curated_course_node_type, 'Units and contextual interpretation', null, 3),
  ('d2f07108-16f3-4ff4-b520-bd338663f9db', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '959cdbf9-547d-4c06-b929-0c25d15900be', 'subtopic'::public.curated_course_node_type, 'The Net Change Theorem', 'Integrating a rate over time gives the change in the original quantity. This principle applies far beyond geometric area.', 2),
  ('068780c8-cd68-485b-a194-1e36e6af26f3', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd2f07108-16f3-4ff4-b520-bd338663f9db', 'concept'::public.curated_course_node_type, 'Position change from velocity and total distance from speed', null, 0),
  ('eac4a55a-195d-4488-958c-68e5d6766e03', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd2f07108-16f3-4ff4-b520-bd338663f9db', 'concept'::public.curated_course_node_type, 'Mass, charge, population, concentration, revenue, and cost accumulation', null, 1),
  ('767d1250-146c-410a-8640-f879fa37d0b9', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd2f07108-16f3-4ff4-b520-bd338663f9db', 'concept'::public.curated_course_node_type, 'Initial amount plus accumulated change', null, 2),
  ('e240e602-c709-48ec-90e5-38c502558632', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd2f07108-16f3-4ff4-b520-bd338663f9db', 'concept'::public.curated_course_node_type, 'Average value of a function on an interval', null, 3),
  ('b693c730-4c32-4aed-bbc9-51b002b85d61', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Substitution and Applications of Integration', 'Substitution extends the antiderivative toolkit by reversing the chain rule. Applications then use slicing and accumulation to compute areas, volumes, work, and other totals.', 11),
  ('d592baec-655e-4be9-ba6b-6c475bf0802e', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'b693c730-4c32-4aed-bbc9-51b002b85d61', 'subtopic'::public.curated_course_node_type, 'Substitution', 'A well-chosen substitution exposes a hidden chain-rule structure and changes both the integrand and, for definite integrals, the bounds.', 0),
  ('eb7183ca-bfc0-494b-9080-074a68a4342f', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd592baec-655e-4be9-ba6b-6c475bf0802e', 'concept'::public.curated_course_node_type, 'Recognizing the inner-function and derivative pattern', null, 0),
  ('1d638df1-5c38-48ba-8348-b76ef3b5af33', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd592baec-655e-4be9-ba6b-6c475bf0802e', 'concept'::public.curated_course_node_type, 'Indefinite integrals and back-substitution', null, 1),
  ('a5f418e0-d203-4f81-a4f7-3f0ae10280f1', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd592baec-655e-4be9-ba6b-6c475bf0802e', 'concept'::public.curated_course_node_type, 'Definite integrals with changed bounds', null, 2),
  ('a7fbfa13-0bb4-43c0-b98e-7038e05d065d', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'd592baec-655e-4be9-ba6b-6c475bf0802e', 'concept'::public.curated_course_node_type, 'Algebraic, exponential, logarithmic, and trigonometric examples', null, 3),
  ('3c04a294-da75-4f35-a6a6-145e3405b222', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'b693c730-4c32-4aed-bbc9-51b002b85d61', 'subtopic'::public.curated_course_node_type, 'Area and volume', 'Integration adds infinitely many thin pieces. The hardest step is choosing a slice whose geometry matches the variable of integration.', 1),
  ('b690f725-27cf-4e01-945d-81859bcdf39c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3c04a294-da75-4f35-a6a6-145e3405b222', 'concept'::public.curated_course_node_type, 'Area between curves and intersection points', null, 0),
  ('73b00973-a5cb-4126-97ef-9f473d087205', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3c04a294-da75-4f35-a6a6-145e3405b222', 'concept'::public.curated_course_node_type, 'Volumes by cross-sections and disks/washers', null, 1),
  ('84fe4e4e-434d-4781-9079-303e0303a550', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3c04a294-da75-4f35-a6a6-145e3405b222', 'concept'::public.curated_course_node_type, 'Shell method as an extension when it simplifies geometry', null, 2),
  ('d01e8341-891a-4c99-8b60-f36e3029a9bc', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '3c04a294-da75-4f35-a6a6-145e3405b222', 'concept'::public.curated_course_node_type, 'Sketching, bounds, units, and reasonableness checks', null, 3),
  ('461b2930-3c10-45ef-ab55-0fb4c4907d49', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'b693c730-4c32-4aed-bbc9-51b002b85d61', 'subtopic'::public.curated_course_node_type, 'Scientific and quantitative applications', 'The integral translates a varying density, force, rate, or distribution into a total or average quantity.', 2),
  ('bef10969-164e-4cfc-a6fd-b6e5b70bfb2c', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '461b2930-3c10-45ef-ab55-0fb4c4907d49', 'concept'::public.curated_course_node_type, 'Work from a variable force and basic spring models', null, 0),
  ('8b87aed0-bb0a-4f8b-92d0-07240a836660', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '461b2930-3c10-45ef-ab55-0fb4c4907d49', 'concept'::public.curated_course_node_type, 'Mass from one-dimensional density', null, 1),
  ('04ae7a24-d76d-49ea-bfd9-e4421787804d', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '461b2930-3c10-45ef-ab55-0fb4c4907d49', 'concept'::public.curated_course_node_type, 'Average value and mean behavior', null, 2),
  ('d5b40396-9a53-4a56-b60d-dd6abc118008', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '461b2930-3c10-45ef-ab55-0fb4c4907d49', 'concept'::public.curated_course_node_type, 'Probability density as enrichment for data-oriented degrees', null, 3),
  ('69d9f1e4-43bd-44dc-a752-420a778b1dcc', 'f818a9a1-0539-4c40-bdea-2792af5f791d', null, 'topic'::public.curated_course_node_type, 'Numerical Integration, Error, and Capstone Modeling', 'Many integrals lack elementary antiderivatives or come only as data. Numerical methods, error awareness, and a final modeling task prepare students to use calculus responsibly in real work.', 12),
  ('f475c01e-0250-4be1-9c8a-044f501897a0', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '69d9f1e4-43bd-44dc-a752-420a778b1dcc', 'subtopic'::public.curated_course_node_type, 'Numerical integration', 'Numerical rules approximate an integral using function samples. Students compare methods and connect each formula to a geometric picture.', 0),
  ('48d0e8cf-b033-4899-a83d-1811d8a6575a', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'f475c01e-0250-4be1-9c8a-044f501897a0', 'concept'::public.curated_course_node_type, 'Left and right sums as baseline methods', null, 0),
  ('41041de9-b946-494c-ab03-03780a6b3c38', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'f475c01e-0250-4be1-9c8a-044f501897a0', 'concept'::public.curated_course_node_type, 'Midpoint and trapezoidal rules', null, 1),
  ('a49abb81-b8ca-4cde-ada7-3f4b5084c898', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'f475c01e-0250-4be1-9c8a-044f501897a0', 'concept'::public.curated_course_node_type, 'Simpson''s rule as an enrichment topic', null, 2),
  ('14f51cc3-6561-4bd2-b0e6-2971954063e4', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'f475c01e-0250-4be1-9c8a-044f501897a0', 'concept'::public.curated_course_node_type, 'Implementation with a spreadsheet, calculator, or short script', null, 3),
  ('beaae755-b8ca-48c8-9cc3-9af123fcfac7', 'f818a9a1-0539-4c40-bdea-2792af5f791d', '69d9f1e4-43bd-44dc-a752-420a778b1dcc', 'subtopic'::public.curated_course_node_type, 'Error and verification', 'A numerical answer is incomplete without an estimate of reliability. Students learn to refine, compare, and communicate approximation error.', 1),
  ('206e93a7-ad48-49af-ae0c-f2284e2515a7', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'beaae755-b8ca-48c8-9cc3-9af123fcfac7', 'concept'::public.curated_course_node_type, 'Absolute and relative error', null, 0),
  ('759ce25c-1547-4e93-bfb4-614197fa6d63', 'f818a9a1-0539-4c40-bdea-2792af5f791d', 'beaae755-b8ca-48c8-9cc3-9af123fcfac7', 'concept'::public.curated_course_node_type, 'Refining the partition and checking stabilization', null, 1),
