insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'textbook'::public.curated_course_resource_kind, 'OpenStax Calculus Volume 1', 'https://openstax.org/details/books/calculus-volume-1', 'Best default open textbook. It covers functions, limits, derivatives, and integration with examples and exercises.', 0),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'textbook'::public.curated_course_resource_kind, 'Calculus: Early Transcendentals', 'Cengage', 'James Stewart. Large exercise bank and conventional sequence; useful for engineering-style fluency and homework selection.', 1),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'textbook'::public.curated_course_resource_kind, 'Thomas'' Calculus', 'Pearson', 'Clear mainstream reference with strong worked examples and applications.', 2),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'textbook'::public.curated_course_resource_kind, 'Calculus: Single Variable', 'Wiley', 'Hughes-Hallett et al. Especially strong for multiple representations, modeling, and conceptual questions.', 3),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'textbook'::public.curated_course_resource_kind, 'Calculus (Spivak)', 'Publish or Perish', 'Michael Spivak. Optional proof-enrichment text for mathematics majors and advanced students; not the sole text for this mixed audience.', 4),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'textbook'::public.curated_course_resource_kind, 'Mathematics for Economists', 'W. W. Norton', 'Simon and Blume. Optional economics bridge for marginal analysis, optimization, and later multivariable work.', 5),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'website'::public.curated_course_resource_kind, 'MIT OpenCourseWare 18.01SC Single Variable Calculus', 'https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/', 'Self-contained lectures, notes, problem sets, solutions, and challenging exams; the strongest all-in-one open companion.', 6),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'website'::public.curated_course_resource_kind, 'Paul''s Online Math Notes - Calculus I', 'https://tutorial.math.lamar.edu/Classes/CalcI/CalcI.aspx', 'Concise explanations and worked problems for quick review and practice.', 7),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'website'::public.curated_course_resource_kind, 'Khan Academy Calculus 1', 'https://www.khanacademy.org/math/calculus-1', 'Guided practice and mastery checks for core Calculus I / AP Calculus AB skills.', 8),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'website'::public.curated_course_resource_kind, 'OpenStax student resources', 'https://openstax.org/details/books/calculus-volume-1', 'Free online reading plus chapter exercises; suitable for an accessible common course baseline.', 9),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'website'::public.curated_course_resource_kind, 'Desmos Graphing Calculator', 'https://www.desmos.com/calculator', 'Fast graphing, tables, sliders, numerical roots, and visual checks.', 10),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'website'::public.curated_course_resource_kind, 'GeoGebra Graphing Calculator', 'https://www.geogebra.org/graphing', 'Interactive graphing and geometry for tangent, accumulation, and optimization explorations.', 11),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'website'::public.curated_course_resource_kind, 'Jupyter', 'https://jupyter.org/', 'Use a spreadsheet or Python/Jupyter for Riemann sums, Newton iterations, numerical integration, data visualization, and reproducible modeling. Require students to explain the mathematics behind any computation.', 12),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'youtube'::public.curated_course_resource_kind, '3Blue1Brown', 'https://www.youtube.com/@3blue1brown', 'Essence of Calculus: short visual sequence for derivatives, integrals, the chain rule, and the Fundamental Theorem; use for intuition, not as a replacement for problem solving.', 13),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'youtube'::public.curated_course_resource_kind, 'Professor Leonard', 'https://www.youtube.com/@ProfessorLeonard', 'Long-form Calculus 1 classroom lectures with detailed examples and pacing suitable for independent review.', 14),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'youtube'::public.curated_course_resource_kind, 'MIT OpenCourseWare', 'https://www.youtube.com/@mitocw', 'University lectures and problem-solving clips aligned with 18.01SC.', 15),
  ('f818a9a1-0539-4c40-bdea-2792af5f791d', 'youtube'::public.curated_course_resource_kind, 'The Organic Chemistry Tutor', 'https://www.youtube.com/@TheOrganicChemistryTutor', 'Focused worked examples for common techniques and exam review.', 16);
